@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  width: 1280px;
  height: 800px;
  overflow: hidden;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
}

.card {
  width: 960px;
  min-height: 620px;
  background: rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 32px;
  padding: 48px 56px;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 32px;
  animation: fadeIn 0.6s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

.error-card {
  text-align: center;
  justify-content: center;
  align-items: center;
  min-height: 620px;
}

.error-icon {
  font-size: 64px;
  margin-bottom: 16px;
}

.error-msg {
  font-size: 20px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.6;
}

.loading-card {
  justify-content: center;
  align-items: center;
  min-height: 620px;
}

.spinner {
  width: 48px;
  height: 48px;
  border: 3px solid rgba(255, 255, 255, 0.15);
  border-top-color: rgba(255, 255, 255, 0.8);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.location-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.location-name {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.5px;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.3);
}

.date-display {
  font-size: 16px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.55);
  letter-spacing: 0.3px;
}

.weather-icon-box {
  font-size: 72px;
  line-height: 1;
  filter: drop-shadow(0 4px 20px rgba(0, 0, 0, 0.3));
}

.main-section {
  display: flex;
  align-items: flex-end;
  gap: 40px;
}

.temp-display {
  display: flex;
  align-items: flex-start;
  gap: 24px;
}

.current-range {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.temp-max {
  font-size: 64px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -2px;
}

.temp-min {
  font-size: 28px;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.5);
  line-height: 1.2;
  letter-spacing: -0.5px;
}

.condition-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 100px;
  font-size: 16px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
  white-space: nowrap;
}

.condition-emoji {
  font-size: 20px;
}

.chart-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.chart-title {
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.4);
  text-transform: uppercase;
  letter-spacing: 1.2px;
}

.chart-container {
  width: 100%;
  height: 260px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 20px;
  padding: 20px 12px 12px 40px;
  position: relative;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.coords-note {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.25);
  letter-spacing: 0.3px;
}

(function () {
  const params = new URLSearchParams(window.location.search);
  const lat = parseFloat(params.get('lat')) || 52.52;
  const lon = parseFloat(params.get('lon')) || 13.405;
  const name = params.get('name') || 'Berlin';

  const now = new Date();
  const todayUTC = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  const todayStr = todayUTC.toISOString().slice(0, 10);

  let dateParam = params.get('date');
  if (!dateParam || !/^\d{4}-\d{2}-\d{2}$/.test(dateParam)) {
    dateParam = todayStr;
  }

  const requestedDate = new Date(dateParam + 'T00:00:00Z');
  const isPast = requestedDate < todayUTC;

  const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

  const url = new URL(endpoint, window.location.origin);
  url.searchParams.set('latitude', lat);
  url.searchParams.set('longitude', lon);
  url.searchParams.set('daily', 'temperature_2m_max,temperature_2m_min,weather_code');
  url.searchParams.set('hourly', 'temperature_2m');
  url.searchParams.set('timezone', 'UTC');
  url.searchParams.set('temperature_unit', 'celsius');
  url.searchParams.set('start_date', dateParam);
  url.searchParams.set('end_date', dateParam);

  const WMO = {
    0: ['Clear sky', '☀️'],
    1: ['Mainly clear', '🌤️'],
    2: ['Partly cloudy', '⛅'],
    3: ['Overcast', '☁️'],
    45: ['Fog', '🌫️'],
    48: ['Depositing rime fog', '🌫️'],
    51: ['Light drizzle', '🌦️'],
    53: ['Moderate drizzle', '🌦️'],
    55: ['Dense drizzle', '🌧️'],
    56: ['Light freezing drizzle', '🌧️'],
    57: ['Dense freezing drizzle', '🌧️'],
    61: ['Slight rain', '🌦️'],
    63: ['Moderate rain', '🌧️'],
    65: ['Heavy rain', '🌧️'],
    66: ['Light freezing rain', '🌨️'],
    67: ['Heavy freezing rain', '🌨️'],
    71: ['Slight snowfall', '🌨️'],
    73: ['Moderate snowfall', '❄️'],
    75: ['Heavy snowfall', '❄️'],
    77: ['Snow grains', '🌨️'],
    80: ['Slight rain showers', '🌦️'],
    81: ['Moderate rain showers', '🌧️'],
    82: ['Violent rain showers', '⛈️'],
    85: ['Slight snow showers', '🌨️'],
    86: ['Heavy snow showers', '❄️'],
    95: ['Thunderstorm', '⛈️'],
    96: ['Thunderstorm with slight hail', '⛈️'],
    99: ['Thunderstorm with heavy hail', '⛈️']
  };

  const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

  function formatDate(d) {
    const dt = new Date(d + 'T00:00:00Z');
    return weekdays[dt.getUTCDay()] + ', ' + months[dt.getUTCMonth()] + ' ' + dt.getUTCDate() + ', ' + dt.getUTCFullYear();
  }

  function renderError(msg) {
    document.getElementById('card').className = 'card error-card';
    document.getElementById('card').innerHTML =
      '<div class="error-icon">⚠️</div><div class="error-msg">' + msg + '</div>';
  }

  function render(data) {
    const daily = data.daily;
    const hourly = data.hourly;

    if (!daily || !hourly || !daily.temperature_2m_max || daily.temperature_2m_max.length === 0) {
      renderError('No weather data available for this date.');
      return;
    }

    const tMax = daily.temperature_2m_max[0];
    const tMin = daily.temperature_2m_min[0];
    const code = daily.weather_code[0];
    const wmo = WMO[code] || ['Unknown', '❓'];
    const conditionLabel = wmo[0];
    const conditionEmoji = wmo[1];

    // Gather 24 hourly temps
    const hours = [];
    for (let i = 0; i < 24 && i < hourly.temperature_2m.length; i++) {
      hours.push(hourly.temperature_2m[i]);
    }

    // Weather icon selection based on code for header
    let bigIcon = conditionEmoji;

    const card = document.getElementById('card');
    card.className = 'card';

    let html = '';
    html += '<div class="header">';
    html += '  <div class="location-info">';
    html += '    <div class="location-name">' + escHtml(name) + '</div>';
    html += '    <div class="date-display">' + formatDate(dateParam) + '</div>';
    html += '    <div class="coords-note">' + lat.toFixed(4) + '°N, ' + lon.toFixed(4) + '°E</div>';
    html += '  </div>';
    html += '  <div class="weather-icon-box">' + bigIcon + '</div>';
    html += '</div>';

    html += '<div class="main-section">';
    html += '  <div class="temp-display">';
    html += '    <div class="current-range">';
    html += '      <div class="temp-max">' + Math.round(tMax) + '°</div>';
    html += '      <div class="temp-min">' + Math.round(tMin) + '°</div>';
    html += '    </div>';
    html += '    <div class="condition-badge"><span class="condition-emoji">' + conditionEmoji + '</span>' + conditionLabel + '</div>';
    html += '  </div>';
    html += '</div>';

    html += '<div class="chart-section">';
    html += '  <div class="chart-title">Hourly Temperature</div>';
    html += '  <div class="chart-container"><canvas id="tempChart"></canvas></div>';
    html += '</div>';

    card.innerHTML = html;

    requestAnimationFrame(function () {
      drawChart(hours);
    });
  }

  function escHtml(s) {
    var d = document.createElement('div');
    d.appendChild(document.createTextNode(s));
    return d.innerHTML;
  }

  function drawChart(temps) {
    const canvas = document.getElementById('tempChart');
    const container = canvas.parentElement;
    const dpr = window.devicePixelRatio || 1;
    const rect = container.getBoundingClientRect();
    canvas.width = (rect.width - 4) * dpr;
    canvas.height = (rect.height - 4) * dpr;
    canvas.style.width = (rect.width - 4) + 'px';
    canvas.style.height = (rect.height - 4) + 'px';

    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    const W = rect.width - 4;
    const H = rect.height - 4;

    const padTop = 24;
    const padBottom = 32;
    const padLeft = 4;
    const padRight = 4;

    const chartW = W - padLeft - padRight;
    const chartH = H - padTop - padBottom;

    const minT = Math.floor(Math.min.apply(null, temps) - 1);
    const maxT = Math.ceil(Math.max.apply(null, temps) + 1);
    const rangeT = maxT - minT || 1;

    function x(i) {
      return padLeft + (i / (temps.length - 1)) * chartW;
    }
    function y(t) {
      return padTop + chartH - ((t - minT) / rangeT) * chartH;
    }

    // Grid lines
    const gridSteps = 5;
    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 6]);
    for (let g = 0; g <= gridSteps; g++) {
      const gy = padTop + (chartH / gridSteps) * g;
      ctx.beginPath();
      ctx.moveTo(padLeft, gy);
      ctx.lineTo(W - padRight, gy);
      ctx.stroke();

      const tempVal = maxT - (rangeT / gridSteps) * g;
      ctx.fillStyle = 'rgba(255,255,255,0.25)';
      ctx.font = '11px Inter, sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(Math.round(tempVal) + '°', -32 + padLeft, gy + 4);
    }
    ctx.setLineDash([]);

    // Gradient fill under curve
    const grad = ctx.createLinearGradient(0, padTop, 0, padTop + chartH);
    grad.addColorStop(0, 'rgba(99, 132, 255, 0.35)');
    grad.addColorStop(1, 'rgba(99, 132, 255, 0.0)');

    ctx.beginPath();
    ctx.moveTo(x(0), padTop + chartH);
    for (let i = 0; i < temps.length; i++) {
      if (i === 0) {
        ctx.lineTo(x(i), y(temps[i]));
      } else {
        const prevX = x(i - 1);
        const prevY = y(temps[i - 1]);
        const currX = x(i);
        const currY = y(temps[i]);
        const cpx1 = prevX + (currX - prevX) * 0.4;
        const cpx2 = prevX + (currX - prevX) * 0.6;
        ctx.bezierCurveTo(cpx1, prevY, cpx2, currY, currX, currY);
      }
    }
    ctx.lineTo(x(temps.length - 1), padTop + chartH);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    // Line
    ctx.beginPath();
    for (let i = 0; i < temps.length; i++) {
      if (i === 0) {
        ctx.moveTo(x(i), y(temps[i]));
      } else {
        const prevX = x(i - 1);
        const prevY = y(temps[i - 1]);
        const currX = x(i);
        const currY = y(temps[i]);
        const cpx1 = prevX + (currX - prevX) * 0.4;
        const cpx2 = prevX + (currX - prevX) * 0.6;
        ctx.bezierCurveTo(cpx1, prevY, cpx2, currY, currX, currY);
      }
    }
    ctx.strokeStyle = 'rgba(130, 160, 255, 0.9)';
    ctx.lineWidth = 2.5;
    ctx.lineJoin = 'round';
    ctx.stroke();

    // Dots
    for (let i = 0; i < temps.length; i++) {
      const cx = x(i);
      const cy = y(temps[i]);

      ctx.beginPath();
      ctx.arc(cx, cy, 3.5, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(130, 160, 255, 0.9)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(15, 12, 41, 0.6)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }

    // Hour labels
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.font = '11px Inter, sans-serif';
    ctx.textAlign = 'center';
    const labelStep = temps.length <= 12 ? 1 : 3;
    for (let i = 0; i < temps.length; i += labelStep) {
      ctx.fillText(String(i).padStart(2, '0') + ':00', x(i), H - 6);
    }

    // Temp labels on dots for every 3 hours
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.font = '600 12px Inter, sans-serif';
    ctx.textAlign = 'center';
    for (let i = 0; i < temps.length; i += 3) {
      ctx.fillText(Math.round(temps[i]) + '°', x(i), y(temps[i]) - 12);
    }
  }

  fetch(url.toString())
    .then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    })
    .then(function (data) {
      render(data);
    })
    .catch(function (err) {
      renderError('Unable to load weather data.<br><span style="font-size:14px;opacity:0.6">' + escHtml(err.message) + '</span>');
    });
})();
